    "punnett_squares_of_up": "Quadros de Punnett de até seis genes, desenhados, e do X; Hardy–Weinberg, a partir de p, de contagens com seu teste χ², ou da característica recessiva; χ² de um cruzamento; mapas gênicos de dois ou três genes, o cromossomo desenhado; as probabilidades da descendência; herdabilidade, pela equação do melhorista; epistasia e qual proporção se ajusta; risco genético, a família desenhada como heredograma; e grupos sanguíneos.",
    "sequence_s_length_bases": "O comprimento de uma sequência, bases, GC ao longo dela e massa, com seu complemento e complemento reverso; tradução em seis fases e as fases de leitura abertas, desenhadas; a roda de códons; T<sub>m</sub> de primers pelos vizinhos mais próximos, seu melting desenhado; DNA e RNA por A<sub>260</sub> e sua pureza; massa, mols e cópias; ligação, o plasmídeo desenhado; digestões de restrição corridas em um gel; as cópias da PCR, ciclo a ciclo; alinhamentos, global e local, com um dot plot; guias CRISPR; motivos de códigos IUPAC; primers para mutagênese e montagem de Gibson; e genomas e suas cópias.",
    "protein_s_mass_pi": "A massa de uma proteína, pI, carga, extinção e hidropatia, desenhadas; os vinte aminoácidos, a titulação de cada um desenhada; concentração de proteína por A<sub>280</sub> ou curva-padrão; cinética enzimática, a partir de V<sub>max</sub> e K<sub>m</sub> ou ajustada a pontos, com inibidores e o gráfico de Lineweaver–Burk; ligação por Hill; dose–resposta, seu IC<sub>50</sub> ajustado; e uma tabela de purificação.",
    "lab": "Laboratório",
    "c_v_c_v": "C₁V₁ = C₂V₂ e diluições seriadas, seus tubos desenhados; preparo de uma solução, a partir da molaridade, fórmula, porcentagem ou de um estoque; contagem de células; crescimento e duplicação, e OD<sub>600</sub>; colônias e UFC/mL; RPM e g da centrífuga; um master mix de PCR; qPCR por ΔΔCt e sua curva-padrão; a média ± 2 EP com barras de erro; R<sub>f</sub> da cromatografia; o microscópio; tamanhos a partir de um gel; eficiência de transformação; semeadura de placas; MOI; radioisótopos; e tampões.",
    "water_potential_osmolarity_and": "Potencial hídrico, osmolaridade e tonicidade, uma hemácia desenhada; razão área/volume; Q₁₀; difusão por Fick; potenciais de membrana por Nernst e por Goldman; energia livre; o débito do coração e a pressão arterial, desenhados; e respiração, seu ATP e o quociente respiratório.",
    "health": "Saúde",
    "diagnostic_tests_their_sensitivity": "Testes diagnósticos, sua sensibilidade, especificidade e valores preditivos, mil pessoas desenhadas; razões de risco e de chances com seus intervalos, e o número necessário para tratar; uma epidemia por SIR e imunidade de rebanho; oxigênio e hemoglobina, o desvio de Bohr desenhado; um potencial de ação por Hodgkin e Huxley; os rins, TFGe e depuração; IMC e energia; e os níveis de um fármaco ao longo das doses. Para aprender, não para tratamento.",
    "ecology": "Ecologia",
    "population_growth_exponential_and": "Crescimento populacional, exponencial e logístico; predadores e presas por Lotka e Volterra; marcação e recaptura; diversidade por Simpson e Shannon; tabelas de vida e sobrevivência; pirâmides de energia; produtividade primária; seleção natural e deriva genética, geração a geração; matrizes de Leslie; competição; espécies, área e rarefação; árvores por UPGMA e neighbour joining; e o relógio molecular.",
