    "common_ions_monatomic_and": "Os íons comuns, monoatômicos e poliatômicos: a carga e a massa molar de cada um, sua cor em água e na chama; o nome de uma fórmula e a fórmula de um nome; e números de oxidação.",
    "ideal_gas_law_pv": "A lei dos gases ideais, PV = nRT, com a massa e a densidade de um gás; a lei geral dos gases; pressões parciais; um gás recolhido sobre água; os volumes dos gases de uma reação; efusão; o ar com a altitude; e a velocidade do som.",
