    "how_acts_in_magnetic": "Como age em um campo magnético: ferromagnético, como o ferro, um ímã em si; paramagnético, atraído fracamente; diamagnético, repelido fracamente; antiferromagnético, com o magnetismo dos átomos se anulando.",
    "crystal_structure": "Estrutura cristalina",
    "how_atoms_packed_in": "Como seus átomos se empacotam no sólido, à temperatura ambiente. Desenhada embaixo, sua célula unitária, a menor caixa que se repete, ou, em uma hexagonal, um prisma de 3; seus átomos contados pela sua parte: um em um vértice é compartilhado por 8 caixas, ou 6 prismas, em uma face por 2. Esferas cinzas: só sua rede, muitos átomos em cada ponto.",
    "abundance_in_crust": "Abundância na crosta",
    "how_much_of_earth": "Quanto da crosta da Terra ele é, em mg/kg, partes por milhão em massa: o oxigênio quase metade, depois o silício. Só traços: poucos átomos por vez, feitos em minérios de urânio e tório; sintético: feito apenas em laboratório.",
    "appearance": "Aparência",
    "what_looks_like_pure": "Como é, puro, à temperatura ambiente.",
    "light_of_atoms_as": "A luz dos seus átomos como gás, do violeta a 380 nm ao vermelho a 750: absorção, luz branca atravessando-o, linhas escuras no arco-íris onde ele retira cores; emissão, aquecido ou em uma faísca, só essas mesmas cores, brilhantes sobre preto. Cada elemento tem linhas próprias, como uma impressão digital: assim o hélio foi achado no Sol antes de na Terra. Suas linhas mais fortes, como o NIST as lista, quanto mais fortes, mais largas; de um elemento cujo átomo não tem nenhuma aqui, as do seu íon. Clique: a outra.",
