    "open_mode": "Modo de abertura",
    "what_toolbar_icon_and": "O que o ícone da barra de ferramentas e Alt+S abrem: Fixo, o pop-up sob o ícone; Destacado, a calculadora em sua própria janela, que cresce ou diminui junto com ela; ou Avançado, a calculadora aberta em uma janela grande com as ferramentas ao lado, cujo botão de recolher a traz de volta no Modo Destacado. Iniciar abre o modo escolhido; o Modo Destacado e o Modo Avançado também estão no menu do ícone da barra de ferramentas, e o Modo Destacado no botão da página.",
