    "language_of_calculator_s": "O idioma dos textos da calculadora: menus, dicas, cartões e resultados. Auto segue o idioma do navegador. Os números e os nomes das teclas permanecem como estão.",
    "calculator_button_on_every": "Botão da calculadora em todos os sites",
    "small_calculator_button_on": "Um pequeno botão de calculadora na lateral de cada página que abre o Modo Destacado. Arraste-o para qualquer lado; ele mantém seu lugar em todas as janelas.",
    "browser_asks_for_access": "O navegador pede acesso aos sites quando você ativa essa opção. Só o botão é adicionado; nada é lido das páginas.",
    "inline_instant_answers_on": "Respostas instantâneas em todos os sites",
    "small_icon_after_maths": "Um pequeno ícone depois das contas de qualquer página: passe o mouse sobre ele para ver a resposta, clique para abri-la na calculadora. Selecione ou clique com o botão direito em qualquer texto para calculá-lo também.",
