    "matrices_ip_networks_complex": "Matrizes, redes IP, números complexos, combinações, lógica, bases, UUIDs e Base64",
    "equations_inequalities_integrals_derivatives": "Equações, inequações, integrais, derivadas, séries, limites, empréstimos e sistemas de equações",
